<script setup lang="ts">
import {ref,computed,onMounted} from 'vue';import {onShow} from '@dcloudio/uni-app';import AppPage from '../AppPage.vue';import AppNavbar from '@/components/AppNavbar.vue';import AppButton from '@/components/AppButton.vue';import BaseCard from '@/components/BaseCard.vue';import SectionHeader from '@/components/SectionHeader.vue';import StatusTag from '@/components/StatusTag.vue';import Stage1Status from './Stage1Status.vue';import QualificationForm from './QualificationForm.vue';import Stage1Files from './Stage1Files.vue';import {useStage1Page} from '../../services/use-stage1-page';import {stage1Service,label} from '../../services/stage1';import type {Data} from '../../services/stage1'
const props=defineProps<{editor?:boolean;query?:Data}>(),p=useStage1Page('qualification_'+(props.query?.id||'new')),{error,busy,loading,pending,dirty}=p
const list=ref<Data|null>(null),record=ref<Data|null>(null),options=ref<Data>({categories:[],qualificationTypes:[]}),form=ref<Data>({type:'BUSINESS_LICENSE',fileIds:[],categoryIds:[],longTerm:false})
const editable=computed(()=>!record.value||['DRAFT','REJECTED'].includes(record.value.status))
function load(){return p.read(async()=>{if(!props.editor)return {list:await stage1Service.read<Data>('/qualifications')};const opts=await stage1Service.options();const current=props.query?.id?await stage1Service.read<Data>('/qualifications/'+props.query.id):null;return {opts,current}},v=>{if(v.list){list.value=v.list;return}options.value=v.opts!;const row=v.current;record.value=row?.payload?row:null;form.value=JSON.parse(JSON.stringify(row?.payload?.qualifications[0]||row?.details||{type:'BUSINESS_LICENSE',fileIds:[],categoryIds:[],longTerm:false}));dirty.value=false})}
async function save(){await p.write(()=>p.command<Data>(record.value?'/qualifications/'+record.value.id+'/draft':'/qualifications',{...(record.value?{expectedVersion:record.value.version}:{}),payload:{qualifications:[Object.fromEntries(Object.entries(form.value).filter(([_,v])=>v!==''))]}},record.value?'PUT':'POST'),v=>{record.value=v;dirty.value=false})}
async function submit(){const yes=await uni.showModal({title:'提交资质审核？',content:'新版本批准前不会延长当前资质有效期。'});if(!yes.confirm)return;if(dirty.value||!record.value)await save();if(!record.value||error.value||pending.value||dirty.value)return;await p.write(()=>p.command<Data>('/qualifications/'+record.value!.id+'/submit',{expectedVersion:record.value!.version}),v=>{record.value=v;dirty.value=false})}
function edit(id?:string){uni.navigateTo({url:'/pages/qualifications/editor/index'+(id?'?id='+id:'')})}
function accepted(v:Data){record.value=v;form.value=v.payload?.qualifications[0]||form.value;dirty.value=false}
onMounted(load);onShow(()=>{if(list.value&&!dirty.value&&!pending.value)void load()})
</script>
<template><AppPage secondary :status="loading&&!list&&!editor?'loading':'ready'"><template #navbar><AppNavbar :title="editor?'资质填写与续期':'资质与有效期'" centered show-back/></template><view class="s1-qualifications stack"><Stage1Status :error="error" :pending="pending" :busy="busy" @recover="p.recover(accepted)" @retry="p.retry(accepted)" @abandon="p.abandon(accepted)"/><template v-if="editor"><BaseCard class="s1-form"><SectionHeader :title="record?label(record.status):'新资质版本'"/><QualificationForm :key="record?.id||'new'" :receipt-key="'qualification_'+(record?.id||'new')" v-model="form" :types="options.qualificationTypes" :categories="options.categories" :disabled="busy||pending||!editable||!p.has('profile.write')" @update:model-value="dirty=true"/><text class="s1-copy">续期待审不延长旧证照有效期；审核通过后按批准日期生效。</text><view v-for="item in record?.history||[]" :key="item.revision"><text>{{label(item.status)}} · {{item.reason||'无补充说明'}}</text></view><AppButton v-if="editable&&p.has('profile.write')" variant="secondary" :loading="busy" :disabled="pending" @click="save">保存草稿</AppButton><AppButton v-if="editable&&p.has('profile.write')" :loading="busy" :disabled="pending" @click="submit">提交资质审核</AppButton></BaseCard></template><template v-else-if="list"><AppButton v-if="p.has('profile.write')" @click="edit()">新增资质</AppButton><BaseCard v-for="draft in list.drafts" :key="draft.id" class="s1-form"><SectionHeader :title="label(draft.payload.qualifications[0].type)"/><StatusTag>{{label(draft.status)}} · 待审记录</StatusTag><AppButton variant="secondary" @click="edit(draft.id)">查看或继续填写</AppButton></BaseCard><BaseCard v-for="q in list.versions" :key="q.id" class="s1-form"><SectionHeader :title="label(q.type)"/><StatusTag :tone="q.status==='APPROVED'?'success':'error'">{{label(q.status)}} · 第 {{q.revision}} 版</StatusTag><text v-if="q.warning" class="s1-warning">{{label(q.warning)}}</text><text>生效 {{q.validFrom}}<br/>截止 {{q.longTerm?'长期':q.validTo}}</text><text v-if="q.revocationReason">撤销原因：{{q.revocationReason}}</text><Stage1Files :model-value="q.details.fileIds||[]" purpose="QUALIFICATION" label="批准附件" disabled/><AppButton v-if="p.has('profile.write')" variant="secondary" @click="edit(q.id)">以此资料填写续期版本</AppButton></BaseCard><BaseCard v-if="!list.versions.length&&!list.drafts.length"><text>暂无资质记录。</text></BaseCard></template><AppButton variant="quiet" :loading="loading" @click="load">重新读取</AppButton></view></AppPage></template><style scoped lang="scss">.s1-qualifications{padding:$space-4 $page-gutter}.s1-form{display:flex;flex-direction:column;gap:$space-4;font-size:15px;line-height:1.7;overflow-wrap:anywhere}.s1-copy{color:$color-text-secondary;font-size:13px}.s1-warning{color:$color-warning;font-weight:600}</style>
